  await setN(12);
  const a = check(12);
  await setN(7);
  const b = check(7);
  await setN(12);
  out.at12 = a; out.at7 = b; out.hasRange = !!range;
  const errs = [], stale = [];
  for (const [id, m] of [["@user/stats-lib", lib], ["@user/report", rep]])
    for (const v of varsOf(m)) { const e = await settle(v); if (!e) continue;
      const line = id + " " + (v._name ?? v.pid ?? "anon") + ": " + e.slice(0, 120);
      // an import binding the apply left behind after its line was removed: nothing reads it, nothing shows it
      if (v._type === 1 && v._outputs.size === 0 && e === v._name + " is not defined") stale.push(line); else errs.push(line); }
  out.errors = errs; out.staleBindings = stale;
  const L = out.libUnchangedRaw;
  out.numbersOk = L && a.missing.length === 0;
  out.noNaN = L && out.numbersOk && !a.bad && !b.bad;
  out.chartOk = L && a.chart.ok && a.chart.dots === 12;
  out.controlsOk = L && !!range && b.missing.length === 0 && b.chart.ok && b.chart.dots === 7;
  out.noErrors = L && out.numbersOk && errs.length === 0;
  out.usesNewLib = L && out.numbersOk && out.importsNew.length === 3;
  out.libUnchanged = L && out.numbersOk;
