const SHAPE = [["spread[0]", "spread.mean"], ["spread[1]", "spread.worst"]];
const DIRECT = rep([...RENAME, ...FMT, ...SHAPE]);
const SHIM = rep([
  ['main.define("summarise", ["module @user/stats-lib", "@variable"], (_, v) => v.import("summarise", _));', 'main.define("summarise", ["module @user/stats-lib", "@variable"], (_, v) => v.import("summarize", "summarise", _));'],
  ['main.define("meanWorst", ["module @user/stats-lib", "@variable"], (_, v) => v.import("meanWorst", _));', 'main.define("meanWorstObj", ["module @user/stats-lib", "@variable"], (_, v) => v.import("meanWorst", "meanWorstObj", _));\n  $def("_shim1", "meanWorst", ["meanWorstObj"], (meanWorstObj) => (v) => { const r = meanWorstObj(v); return [r.mean, r.worst]; });'],
  ['main.define("fmt", ["module @user/stats-lib", "@variable"], (_, v) => v.import("fmt", _));', 'main.define("fmtOpts", ["module @user/stats-lib", "@variable"], (_, v) => v.import("fmt", "fmtOpts", _));\n  $def("_shim2", "fmt", ["fmtOpts"], (fmtOpts) => (v, digits = 2) => fmtOpts(v, { digits }));'],
]);
const LIB_ALIAS = LIB_NEW.replace('  return main;', '  $def("_sl7", "summarise", ["summarize"], (summarize) => summarize);\n  return main;');
const W = (path, content) => ({ tool: "write_file", args: { file_path: path, content } });
const R = "/src/@user/report.js", LB = "/src/@user/stats-lib.js";
const NEG = process.env.M34_NEG || "";
const oracle =
    NEG === "unchanged" ? [{ tool: "read_file", args: { file_path: R } }]
  : NEG === "renameonly" ? [W(R, rep(RENAME))]
  // fmt fixed, the shape change left: spread[0] / spread[1] of {mean, worst} -> "—" and "NaN×", rules gone
  : NEG === "loudonly" ? [W(R, rep([...RENAME, ...FMT]))]
  // shape fixed, fmt(x, 2) left: the number lands where { digits } is destructured, so every value shows 0 decimals
  : NEG === "noformat" ? [W(R, rep([...RENAME, ...SHAPE]))]
  : NEG === "revert" ? [W(LB, LIB_OLD)]
  : NEG === "alias" ? [W(LB, LIB_ALIAS), W(R, rep([...FMT, ...SHAPE]))]
  : NEG === "shim" ? [{ tool: "read_file", args: { file_path: LB } }, W(R, SHIM)]
  : [{ tool: "read_file", args: { file_path: LB } }, W(R, DIRECT)];

